function recordResult({mode,category,concept,correct,time,maxTime,timeout=false,unsure=false,confidence='unsure',prompt='',given='',expected='',explanation=''}){
  const targets=[ensureStat(progress.conceptStats,statKey(category,concept)),ensureStat(progress.categoryStats,category)];
  targets.forEach(s=>{
    s.attempts++;s.totalTime+=Math.max(0,safeNum(time));s.lastSeen=Date.now();
    if(correct){s.correct++;s.streak++;s.bestStreak=Math.max(s.bestStreak,s.streak);}else{s.wrong++;s.streak=0;}
    if(mode==='mcq'){s.mcqAttempts++;if(correct)s.mcqCorrect++;}
    if(mode==='recall'){s.recallAttempts++;if(correct)s.recallCorrect++;}
    if(mode==='smart'){s.smartAttempts++;if(correct)s.smartCorrect++;}
    if(timeout)s.timeouts++;
    if(unsure){s.unsure++;if(!correct)s.unsureWrong++;}
    if(correct&&maxTime&&time>=maxTime*.8)s.slowCorrect++;
  });
  scheduleReview(targets[0],correct,confidence);
  if(!correct){progress.mistakes=progress.mistakes||[];progress.mistakes.unshift({id:`${Date.now()}-${Math.random().toString(36).slice(2,6)}`,date:Date.now(),category,concept,mode,prompt,given:given||'No answer',expected:expected||concept,explanation:explanation||(studyNotes[category]?.[concept]?.[0]||''),resolved:false});progress.mistakes=progress.mistakes.slice(0,100);}
  saveProgress();
}
