function isMastered(s){return s.attempts>=4&&s.correct/s.attempts>=.8&&(s.correctDays||[]).length>=2&&s.recallCorrect>=2;}
function dueConceptRows(){const now=Date.now();return allConceptRows().filter(x=>x.stat.attempts&&(!x.stat.dueAt||x.stat.dueAt<=now)).sort((a,b)=>(a.stat.dueAt||0)-(b.stat.dueAt||0));}
function weaknessScore(s){if(!s.attempts)return 35;const accuracy=s.correct/s.attempts;const slow=s.slowCorrect/Math.max(1,s.correct);const timeout=s.timeouts/s.attempts;const repeat=Math.min(20,s.wrong*4);return Math.round((1-accuracy)*55+slow*12+timeout*13+repeat);}
function allConceptRows(){return categories.flatMap(category=>concepts[category].map(concept=>({category,concept,stat:getConceptStat(category,concept)})));}
