function startElimination(){
  clearInterval(elimState.timer);
  const examSet=buildEliminationSet();
  elimState={questions:examSet.map(q=>({...q,options:q.options.map((t,i)=>({text:t,originalIndex:i}))})),answers:Array(examSet.length).fill(null),unsure:Array(examSet.length).fill(false),timeSpent:Array(examSet.length).fill(0),index:0,seconds:3600,timer:null,startSeconds:3600,submitted:false,questionEnteredAt:Date.now()};
  elimState.questions.forEach(q=>q.options=shuffle(q.options));
  show('elim');renderElimQuestion();updateElimTimer();
  elimState.timer=setInterval(()=>{elimState.seconds--;updateElimTimer();if(elimState.seconds<=0)submitElimination(true);},1000);
}
function captureElimTime(){if(!elimState.questionEnteredAt)return;const delta=(Date.now()-elimState.questionEnteredAt)/1000;elimState.timeSpent[elimState.index]+=Math.max(0,Math.min(delta,300));elimState.questionEnteredAt=Date.now();}
function updateElimTimer(){const m=Math.floor(elimState.seconds/60),s=elimState.seconds%60;$('elimTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function renderElimQuestion(){
  elimState.questionEnteredAt=Date.now();const q=elimState.questions[elimState.index];
  $('elimProgress').textContent=`Question ${elimState.index+1} of 100`;$('elimCategory').textContent=q.category;$('elimQuestion').textContent=q.question;$('elimUnsure').checked=elimState.unsure[elimState.index];$('elimOptions').innerHTML='';
  q.options.forEach((opt,i)=>{const b=document.createElement('button');b.type='button';b.className='option'+(elimState.answers[elimState.index]===i?' selected':'');b.textContent=`${String.fromCharCode(65+i)}. ${opt.text}`;b.addEventListener('click',()=>{captureElimTime();elimState.answers[elimState.index]=i;renderElimQuestion();});$('elimOptions').appendChild(b);});
  $('elimPrev').disabled=elimState.index===0;$('elimNext').disabled=elimState.index===99;const answered=elimState.answers.filter(v=>v!==null).length;$('answeredCount').textContent=`Answered ${answered}/100 · ${elimState.unsure.filter(Boolean).length} marked unsure`;$('elimBar').style.width=`${answered}%`;
}
function submitElimination(auto){
  if(elimState.submitted)return;if(!auto&&!confirm('Submit your 100-item elimination now?'))return;captureElimTime();elimState.submitted=true;rememberQuestionSet(elimState.questions);clearInterval(elimState.timer);
  let score=0;const stats={};categories.forEach(c=>stats[c]={correct:0,total:0,time:0});const misses=[];let unsureWrong=0,slowCorrect=0;
  elimState.questions.forEach((q,i)=>{const chosen=elimState.answers[i],chosenOriginal=chosen===null?null:q.options[chosen].originalIndex,ok=chosenOriginal===q.answer,time=elimState.timeSpent[i],given=chosen===null?'No answer':q.options[chosen].text,expected=q.options.find(o=>o.originalIndex===q.answer).text;stats[q.category].total++;stats[q.category].time+=time;if(ok){score++;stats[q.category].correct++;if(time>=36)slowCorrect++;}else{if(elimState.unsure[i])unsureWrong++;misses.push({q,chosen:given,correct:expected,time,unsure:elimState.unsure[i]});}recordResult({mode:'mcq',category:q.category,concept:q.concept,correct:ok,time,maxTime:36,timeout:chosen===null,unsure:elimState.unsure[i],confidence:elimState.unsure[i]?'unsure':'confident',prompt:q.question,given,expected,explanation:q.explanation});});
  const used=elimState.startSeconds-elimState.seconds;addAttempt({type:competitionMode?'Competition · Elimination':'Elimination',score,max:100,seconds:used});
  $('elimScore').textContent=`${score}/100 (${score}%)`;$('elimTimeUsed').textContent=`Time used: ${Math.floor(used/60)}m ${used%60}s${auto?' · Time expired':''}`;
  $('categoryAnalytics').innerHTML=categories.map(c=>{const x=stats[c],pc=pct(x.correct,x.total),avg=Math.round(x.time/x.total);return `<div><h4>${c}</h4><p>${x.correct}/${x.total} · ${pc}%</p><p class="small">Avg ${avg}s/question</p></div>`;}).join('');
  const weakest=Object.entries(stats).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total))[0];
  $('elimSmartSummary').innerHTML=`Your weakest category in this attempt was <b>${weakest[0]}</b> at ${pct(weakest[1].correct,weakest[1].total)}%. ${unsureWrong?`${unsureWrong} missed question${unsureWrong===1?' was':'s were'} also marked unsure. `:''}${slowCorrect?`${slowCorrect} correct answer${slowCorrect===1?' took':'s took'} 36 seconds or more, so speed may also need work.`:'Your correct answers were generally within the target average pace.'}`;
  $('elimReview').innerHTML=misses.length?misses.map(m=>`<div class="review-item"><h4>${m.q.category} · ${m.q.concept}</h4><p><strong>${m.q.question}</strong></p><p>Your answer: ${m.chosen}${m.unsure?' · marked unsure':''}</p><p>Correct answer: ${m.correct}</p><p>Time on question: ${Math.round(m.time)}s</p><p>${m.q.explanation}</p></div>`).join(''):'<div class="review-item"><h4>Perfect score</h4><p>No missed questions.</p></div>';
  $('elimReview').classList.add('hidden');renderHomeProgress();if(competitionMode){competitionElimScore=score;show('finalIntro');}else show('elimResults');
}

function startFinal(){
  clearInterval(finalState.timer);finalState={levels:['easy','average','difficult'],levelIndex:0,index:0,answers:{easy:[],average:[],difficult:[]},seconds:15,timer:null,locked:false,questionStartedAt:0,sets:{easy:shuffle(finalQuestions.easy.map(q=>({...q,prompt:finalPromptFor('easy',q),answers:finalAnswersFor(q)}))),average:shuffle(finalQuestions.average.map(q=>({...q,prompt:finalPromptFor('average',q),answers:finalAnswersFor(q)}))),difficult:shuffle(finalQuestions.difficult.map(q=>({...q,prompt:finalPromptFor('difficult',q),answers:finalAnswersFor(q)})))}};show('finalQuiz');renderFinalQuestion();
}
function levelSeconds(level){return level==='easy'?15:level==='average'?20:30;}
function levelPoints(level){return level==='easy'?3:level==='average'?5:7;}
function renderFinalQuestion(){
  clearInterval(finalState.timer);finalState.locked=false;const level=finalState.levels[finalState.levelIndex],set=finalState.sets[level],q=set[finalState.index];finalState.seconds=levelSeconds(level);finalState.questionStartedAt=Date.now();
  $('finalLevel').textContent=`${level[0].toUpperCase()+level.slice(1)} · ${levelPoints(level)} points`;$('finalProgress').textContent=`Question ${finalState.index+1} of 10`;$('finalCategory').textContent=q.category;$('finalPrompt').textContent=q.prompt;$('finalAnswer').value='';$('finalForm').classList.remove('hidden');$('finalFeedback').className='feedback hidden';$('finalFeedback').replaceChildren();$('finalNext').classList.add('hidden');$('finalAnswer').focus();updateFinalTimer();finalState.timer=setInterval(()=>{finalState.seconds--;updateFinalTimer();if(finalState.seconds<=0)submitFinalAnswer(true);},1000);
}
function updateFinalTimer(){const level=finalState.levels[finalState.levelIndex],max=levelSeconds(level);$('finalTimer').textContent=finalState.seconds;$('finalTimeBar').style.width=`${Math.max(0,finalState.seconds/max*100)}%`;}
function submitFinalAnswer(timeout){
  if(finalState.locked)return;finalState.locked=true;clearInterval(finalState.timer);const level=finalState.levels[finalState.levelIndex],q=finalState.sets[level][finalState.index],raw=timeout?'':$('finalAnswer').value,match=timeout?{ok:false,method:'empty'}:matchAnswer(raw,q.answers,q.concept),ok=match.ok,max=levelSeconds(level),time=Math.min(max,(Date.now()-finalState.questionStartedAt)/1000);finalState.answers[level].push({q,raw:timeout?'Timed out':raw,ok,time,matchMethod:match.method});recordResult({mode:'recall',category:q.category,concept:q.concept,correct:ok,time,maxTime:max,timeout,prompt:q.prompt,given:raw||'Timed out',expected:displayAnswerFor(q.concept),explanation:q.explanation});
  const expected=displayAnswerFor(q.concept),status=answerStatus(match,ok,timeout),feedback=$('finalFeedback');feedback.className=`feedback ${status.tone}`;feedback.innerHTML=answerFeedbackMarkup({match,ok,expected,explanation:q.explanation,category:q.category,timeout});$('finalForm').classList.add('hidden');$('finalNext').textContent=level==='difficult'&&finalState.index===9?'See Results':'Next Question';$('finalNext').classList.remove('hidden');$('finalNext').focus();
}
function nextFinalQuestion(){
  if(!finalState.locked)return;finalState.index++;if(finalState.index>=10){finalState.levelIndex++;finalState.index=0;if(finalState.levelIndex>=finalState.levels.length){finishFinal();return;}}renderFinalQuestion();
}
function finishFinal(){
  let total=0,max=0;const breakdown=[],allAnswers=[];finalState.levels.forEach(level=>{const pts=levelPoints(level),arr=finalState.answers[level],correct=arr.filter(x=>x.ok).length;total+=correct*pts;max+=10*pts;breakdown.push({level,correct,points:correct*pts,max:10*pts,avg:arr.reduce((a,x)=>a+x.time,0)/10});arr.forEach(x=>allAnswers.push({level,...x}));});
  addAttempt({type:competitionMode?'Competition · Final':'Final',score:total,max,seconds:Math.round(finalState.levels.flatMap(l=>finalState.answers[l]).reduce((a,x)=>a+x.time,0))});
  $('finalScore').textContent=`${total}/${max} points`;$('finalBreakdown').innerHTML=breakdown.map(b=>`<div><h4>${b.level[0].toUpperCase()+b.level.slice(1)}</h4><p>${b.correct}/10 correct · ${b.points}/${b.max} pts</p><p class="small">Avg ${Math.round(b.avg)}s response</p></div>`).join('');
  const worst=[...breakdown].sort((a,b)=>a.correct-b.correct)[0];$('finalSmartSummary').innerHTML=competitionMode?`Competition simulation complete: <b>${competitionElimScore}/100</b> in elimination and <b>${total}/${max}</b> points in identification. Your weakest identification level was ${worst.level}.`:`Your weakest identification level this run was <b>${worst.level}</b> with ${worst.correct}/10 correct. The persistent analytics will also compare your multiple-choice recognition with typed recall by category.`;
  $('finalReview').innerHTML=allAnswers.map(m=>`<div class="review-item"><h4>${escapeHtml(m.level.toUpperCase())} · ${escapeHtml(m.q.category)} · ${escapeHtml(m.q.concept)}</h4><p><strong>${escapeHtml(m.q.prompt)}</strong></p><p>${m.matchMethod==='close'?'Close spelling — no point.':m.ok?'Correct.':'Different answer.'}</p><p>Your answer: ${escapeHtml(m.raw||'No answer')}</p><p>Accepted answer: ${escapeHtml(displayAnswerFor(m.q.concept))}</p><p>Response time: ${Math.round(m.time)}s</p><p>${escapeHtml(m.q.explanation)}</p></div>`).join('');
  $('finalReview').classList.add('hidden');renderHomeProgress();show('finalResults');competitionMode=false;
}

function getStudyQueue(limit=10){
  const rows=allConceptRows();
  const wrong=rows.filter(x=>x.stat.wrong>0).sort((a,b)=>weaknessScore(b.stat)-weaknessScore(a.stat));
  const slow=rows.filter(x=>x.stat.wrong===0&&x.stat.slowCorrect>0).sort((a,b)=>b.stat.slowCorrect-a.stat.slowCorrect);
  const untested=shuffle(rows.filter(x=>!x.stat.attempts));
  const combined=[...wrong,...slow,...untested];const seen=new Set();return combined.filter(x=>{const k=statKey(x.category,x.concept);if(seen.has(k))return false;seen.add(k);return true;}).slice(0,limit);
}
function openAnalytics(){renderAnalytics();show('analyticsScreen');}
function renderAnalytics(){
  const conceptRows=allConceptRows(),tested=conceptRows.filter(x=>x.stat.attempts>0),totals=tested.reduce((a,x)=>({attempts:a.attempts+x.stat.attempts,correct:a.correct+x.stat.correct}),{attempts:0,correct:0});
  const recallAttempts=categories.reduce((a,c)=>a+getCategoryStat(c).recallAttempts,0),recallCorrect=categories.reduce((a,c)=>a+getCategoryStat(c).recallCorrect,0),wrongConcepts=conceptRows.filter(x=>x.stat.wrong>0).length;
  $('analyticsSummary').innerHTML=`<div><strong>${progress.attempts.length}</strong><span>Saved sessions</span></div><div><strong>${tested.length}/130</strong><span>Concepts tested</span></div><div><strong>${totals.attempts?pct(totals.correct,totals.attempts):0}%</strong><span>Overall answer accuracy</span></div><div><strong>${recallAttempts?pct(recallCorrect,recallAttempts):0}%</strong><span>Typed recall accuracy</span></div>`;
  const queue=getStudyQueue(10);$('studyQueue').innerHTML=queue.length?queue.map((x,i)=>{const s=x.stat,st=statusForStat(s),reason=s.wrong?`${s.wrong} miss${s.wrong===1?'':'es'} · ${pct(s.correct,s.attempts)}% accuracy`:s.slowCorrect?`${s.slowCorrect} slow correct answer${s.slowCorrect===1?'':'s'}`:'Not tested yet';return `<div class="priority-item"><div><strong>${i+1}. ${x.concept}</strong><span>${x.category} · ${reason}</span></div><span class="status-pill ${st.cls}">${st.label}</span></div>`;}).join(''):'<p class="empty-state">Complete a quiz to create a study queue.</p>';
  $('persistentCategoryAnalytics').innerHTML=categories.map(c=>{const s=getCategoryStat(c),acc=pct(s.correct,s.attempts),mcq=pct(s.mcqCorrect,s.mcqAttempts),rec=pct(s.recallCorrect,s.recallAttempts),avg=s.attempts?Math.round(s.totalTime/s.attempts):0,st=statusForStat(s);return `<div><h4>${c}</h4><p>${s.attempts?`${acc}% overall · ${s.attempts} answers`:'Untested'}</p><p class="small">MCQ: ${s.mcqAttempts?mcq+'%':'—'} · Recall: ${s.recallAttempts?rec+'%':'—'} · Avg: ${s.attempts?avg+'s':'—'}</p><div class="metric-line"><span style="width:${acc}%"></span></div><p class="small"><span class="status-pill ${st.cls}">${st.label}</span></p></div>`;}).join('');
  renderPatternInsights(wrongConcepts);
  const weak=conceptRows.filter(x=>x.stat.wrong>0||x.stat.slowCorrect>0).sort((a,b)=>weaknessScore(b.stat)-weaknessScore(a.stat)).slice(0,15);
  $('weakConcepts').innerHTML=weak.length?`<table class="weak-table"><thead><tr><th>Concept</th><th>Category</th><th>Accuracy</th><th>Misses</th><th>Avg time</th><th>Status</th></tr></thead><tbody>${weak.map(x=>{const s=x.stat,st=statusForStat(s);return `<tr><td><strong>${x.concept}</strong></td><td>${x.category}</td><td>${pct(s.correct,s.attempts)}%</td><td>${s.wrong}</td><td>${Math.round(s.totalTime/s.attempts)}s</td><td><span class="status-pill ${st.cls}">${st.label}</span></td></tr>`;}).join('')}</tbody></table>`:'<p class="empty-state">No weak concepts detected yet.</p>';
  $('attemptHistory').innerHTML=progress.attempts.length?progress.attempts.slice(0,12).map(a=>`<div class="history-item"><div><strong>${a.type}</strong><span>${formatDate(a.date)}</span></div><div class="right"><strong>${a.score}/${a.max}</strong><span>${a.seconds?`${Math.floor(a.seconds/60)}m ${a.seconds%60}s`:''}</span></div></div>`).join(''):'<p class="empty-state">No saved sessions yet.</p>';
}
function renderPatternInsights(wrongConcepts){
  const insights=[];
  categories.forEach(c=>{const s=getCategoryStat(c);if(s.mcqAttempts>=5&&s.recallAttempts>=2){const m=pct(s.mcqCorrect,s.mcqAttempts),r=pct(s.recallCorrect,s.recallAttempts);if(m-r>=20)insights.push({type:'warn',text:`${c}: recognition is ${m}% in MCQ but typed recall is ${r}%. You may recognize answers better than you can retrieve them without choices.`});if(r-m>=20)insights.push({type:'warn',text:`${c}: typed recall is stronger than MCQ performance (${r}% vs ${m}%). Distractors or application questions may be causing mistakes.`});}});
  const repeated=allConceptRows().filter(x=>x.stat.wrong>=2).sort((a,b)=>b.stat.wrong-a.stat.wrong).slice(0,4);repeated.forEach(x=>insights.push({type:'bad',text:`${x.concept} has been missed ${x.stat.wrong} times. Treat this as a recurring concept gap, not a one-off mistake.`}));
  const slowCats=categories.map(c=>({c,s:getCategoryStat(c)})).filter(x=>x.s.correct>=3&&x.s.slowCorrect/x.s.correct>=.35).sort((a,b)=>(b.s.slowCorrect/b.s.correct)-(a.s.slowCorrect/a.s.correct)).slice(0,3);slowCats.forEach(x=>insights.push({type:'warn',text:`${x.c}: ${pct(x.s.slowCorrect,x.s.correct)}% of your correct answers were near the time limit or slower than the elimination target pace. Accuracy may be okay, but retrieval speed needs work.`}));
  const unsureWrong=categories.reduce((a,c)=>a+getCategoryStat(c).unsureWrong,0);if(unsureWrong>=3)insights.push({type:'warn',text:`You have ${unsureWrong} incorrect answers that you explicitly marked unsure. Your uncertainty signal is useful: these should be reviewed before random new material.`});
  if(!insights.length&&progress.attempts.length)insights.push({type:'good',text:`No strong recurring pattern is established yet. You have ${wrongConcepts} concepts with at least one miss; more delayed attempts will make the pattern detection more reliable.`});
  if(!progress.attempts.length)insights.push({type:'good',text:'There is no performance history yet. Complete a quiz or Smart Drill and this section will begin detecting patterns.'});
  $('patternInsights').innerHTML=insights.slice(0,8).map(i=>`<div class="insight-item ${i.type}">${i.text}</div>`).join('');
}

function smartQuestionScore(q){const s=getConceptStat(q.category,q.concept);if(!s.attempts)return 40;return weaknessScore(s)+(Date.now()-s.lastSeen>3*24*60*60*1000?8:0);}
function smartReasonFor(q){const s=getConceptStat(q.category,q.concept);if(!s.attempts)return 'Unseen concept';if(s.wrong>=2)return 'Repeated mistake';if(s.wrong)return 'Recent weak concept';if(s.slowCorrect)return 'Speed practice';return 'Retention check';}
function buildSmartSet(){
  const scored=shuffle(questionPool).map(q=>({q,score:smartQuestionScore(q)}));const chosen=[];const used=new Set();
  categories.forEach(c=>{const candidates=scored.filter(x=>x.q.category===c).sort((a,b)=>b.score-a.score);if(candidates[0]){chosen.push(candidates[0].q);used.add(statKey(candidates[0].q.category,candidates[0].q.concept));}});
  scored.sort((a,b)=>b.score-a.score).forEach(x=>{const k=statKey(x.q.category,x.q.concept);if(chosen.length<20&&!used.has(k)){chosen.push(x.q);used.add(k);}});return shuffle(chosen);
}
function openSmartDrillIntro(){const set=buildSmartSet(),counts={weak:0,unseen:0,speed:0,retention:0};set.forEach(q=>{const r=smartReasonFor(q);if(r==='Unseen concept')counts.unseen++;else if(r.includes('mistake')||r.includes('weak'))counts.weak++;else if(r==='Speed practice')counts.speed++;else counts.retention++;});$('smartDrillPlan').innerHTML=`<div><strong>${counts.weak}</strong> weak/repeated-mistake questions</div><div><strong>${counts.unseen}</strong> untested coverage questions</div><div><strong>${counts.speed}</strong> speed-practice questions</div><div><strong>${counts.retention}</strong> retention checks</div>`;smartState.questions=set;show('smartDrillIntro');}
function startSmartDrill(){if(!smartState.questions.length)smartState.questions=buildSmartSet();smartState={questions:smartState.questions.map(q=>({...q,options:q.options.map((text,i)=>({text,originalIndex:i}))})),index:0,correct:0,startedAt:Date.now(),questionStartedAt:0,answered:false,results:[]};smartState.questions.forEach(q=>q.options=shuffle(q.options));show('smartDrill');renderSmartQuestion();}
function renderSmartQuestion(){const q=smartState.questions[smartState.index];smartState.answered=false;smartState.questionStartedAt=Date.now();$('smartProgress').textContent=`Question ${smartState.index+1} of ${smartState.questions.length}`;$('smartCategory').textContent=q.category;$('smartReason').textContent=smartReasonFor(q);$('smartQuestion').textContent=q.question;$('smartFeedback').className='feedback hidden';$('smartFeedback').innerHTML='';$('smartNext').classList.add('hidden');$('smartOptions').innerHTML='';q.options.forEach((opt,i)=>{const b=document.createElement('button');b.type='button';b.className='option';b.textContent=`${String.fromCharCode(65+i)}. ${opt.text}`;b.addEventListener('click',()=>answerSmart(i));$('smartOptions').appendChild(b);});updateSmartTimer();}
function updateSmartTimer(){if(!document.getElementById('smartDrill').classList.contains('active')||smartState.answered)return;const sec=Math.floor((Date.now()-smartState.questionStartedAt)/1000);$('smartTimer').textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;requestAnimationFrame(updateSmartTimer);}
function answerSmart(index){if(smartState.answered)return;smartState.answered=true;const q=smartState.questions[smartState.index],chosen=q.options[index],ok=chosen.originalIndex===q.answer,time=(Date.now()-smartState.questionStartedAt)/1000,correctText=q.options.find(o=>o.originalIndex===q.answer).text,match={ok,method:ok?'exact':'wrong'};if(ok)smartState.correct++;smartState.results.push({q,chosen:chosen.text,correct:correctText,ok,time});recordResult({mode:'smart',category:q.category,concept:q.concept,correct:ok,time,maxTime:36,prompt:q.question,given:chosen.text,expected:correctText,explanation:q.explanation});[...$('smartOptions').children].forEach((b,i)=>{b.disabled=true;const o=q.options[i];if(o.originalIndex===q.answer)b.classList.add('selected');});const f=$('smartFeedback'),status=answerStatus(match,ok);f.className=`feedback ${status.tone}`;f.innerHTML=answerFeedbackMarkup({match,ok,expected:correctText,explanation:q.explanation,category:q.category});$('smartNext').textContent=smartState.index===smartState.questions.length-1?'Finish Drill':'Next Question';$('smartNext').classList.remove('hidden');}
function nextSmartQuestion(){if(!smartState.answered)return;smartState.index++;if(smartState.index>=smartState.questions.length){finishSmartDrill();return;}renderSmartQuestion();}
function finishSmartDrill(){const used=Math.round((Date.now()-smartState.startedAt)/1000);addAttempt({type:'Smart Drill',score:smartState.correct,max:smartState.questions.length,seconds:used});$('smartScore').textContent=`${smartState.correct}/${smartState.questions.length} correct`;
  const misses=smartState.results.filter(r=>!r.ok),slow=smartState.results.filter(r=>r.ok&&r.time>=36);$('smartResultSummary').innerHTML=`${misses.length?`You missed ${misses.length} concepts. The next Smart Drill will automatically raise their priority.`:'No misses in this drill.'} ${slow.length?`${slow.length} correct answer${slow.length===1?' was':'s were'} slow enough to remain in the practice queue.`:''}`;
  $('smartReview').innerHTML=misses.length?misses.map(m=>`<div class="review-item"><h4>${m.q.category} · ${m.q.concept}</h4><p><strong>${m.q.question}</strong></p><p>Your answer: ${m.chosen}</p><p>Correct answer: ${m.correct}</p><p>${m.q.explanation}</p></div>`).join(''):'<div class="review-item"><h4>Clean drill</h4><p>You answered every Smart Drill question correctly.</p></div>';renderHomeProgress();show('smartResults');}

function exportProgressData(){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`it-quiz-bee-progress-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function resetProgressData(){if(!confirm('Delete all saved quiz history and analytics? This reset will sync to your account if cloud sync is on.'))return;progress=emptyProgress();saveProgress();renderAnalytics();renderHomeProgress();}

initTheme();
renderHomeProgress();
initializeCloudSync();
